GithubComments = {
    _accessToken: undefined,
    _clientId: undefined,
    _clientSecret: undefined,
    _owner: undefined,
    _repos: undefined,
    _emojiJson: undefined,
    _emojiLoadPromise: undefined,
    ACCEPT_JSON: "application/json",
    ACCESS_TOKEN_NAME: 'GIT_ACCESS_TOKEN',
    EMOJI_JSON: 'EMOJI_JSON',
    CORS_ANYWHERE: 'https://jithee-cors.azurewebsites.net/',
    PARAM_CODE: 'code',
    SCOPE: "public_repo",
    GITHUB_GPI: 'https://api.github.com',
    PER_PAGE: 100,
    CACHE_TTL: 5 * 60 * 1000,
    COMMENTS_CACHE_PREFIX: 'GITHUB_COMMENTS_',
    COMMENTS_COUNT_CACHE_PREFIX: 'GITHUB_COMMENTS_COUNT_',
    ERROR: {
        ISSUE_NOT_FOUND: "Comment issue not found, maybe not created.",
        UNHANDLE_EXCEPTION: "Error",
        NOT_LOGIN: "User has not login.",
        ISSUE_ID_NOT_EXIST: "The issue id not exist"
    },
    Request: function(options) {
        return new Promise(function(resolve, reject) {
            $.ajax(options)
                .done(function(data, textStatus, request) {
                    resolve({
                        data: data,
                        request: request
                    });
                })
                .fail(function(request, status, error) {
                    reject({
                        request: request,
                        status: status,
                        error: error
                    });
                });
        });
    },
    Cache: {
        Get: function(key) {
            var raw = localStorage.getItem(key);
            if (!raw) return undefined;

            try {
                var cached = JSON.parse(raw);
                if (!cached.expiresAt || cached.expiresAt <= Date.now()) {
                    localStorage.removeItem(key);
                    return undefined;
                }
                return cached.value;
            } catch (error) {
                localStorage.removeItem(key);
                return undefined;
            }
        },
        Set: function(key, value) {
            localStorage.setItem(key, JSON.stringify({
                expiresAt: Date.now() + GithubComments.CACHE_TTL,
                value: value
            }));
        },
        ClearIssue: function(issueId) {
            var commentKeyPrefix = GithubComments.COMMENTS_CACHE_PREFIX + issueId + '_';
            var countKey = GithubComments.COMMENTS_COUNT_CACHE_PREFIX + issueId;
            var keys = [];

            for (var i = 0; i < localStorage.length; i++) {
                var key = localStorage.key(i);
                if (key && key.indexOf(commentKeyPrefix) === 0) keys.push(key);
            }

            keys.push(countKey);
            for (var i = 0; i < keys.length; i++) {
                localStorage.removeItem(keys[i]);
            }
        }
    },
    Init: function(owner, repository, clientId, clientSecret) {
        GithubComments._repos = repository;
        GithubComments._owner = owner;
        GithubComments._clientId = clientId;
        GithubComments._clientSecret = clientSecret;

        // init access token
        var accessToken = localStorage.getItem(GithubComments.ACCESS_TOKEN_NAME);
        if (accessToken) GithubComments._accessToken = accessToken;

        // init emoji
        var emojiJson = localStorage.getItem(GithubComments.EMOJI_JSON);
        if (emojiJson) {
            GithubComments._emojiJson = JSON.parse(emojiJson);
            GithubComments._emojiLoadPromise = Promise.resolve(GithubComments._emojiJson);
        } else {
            GithubComments._emojiLoadPromise = GithubComments.Emoji.Init();
            GithubComments._emojiLoadPromise.catch(function(error) {
                console.error('Unable to load GitHub emoji metadata.', error);
            });
        }
    },
    User: {
        _userInfo: undefined,
        REQUEST_TIMEOUT: 15000,
        GetErrorMessage: function(error, fallback) {
            if (error.status === 'timeout') return 'GitHub 登录请求超时，请稍后重试。';
            if (error.request && error.request.responseJSON && error.request.responseJSON.error_description) {
                return error.request.responseJSON.error_description;
            }
            if (error.request && error.request.responseJSON && error.request.responseJSON.message) {
                return error.request.responseJSON.message;
            }
            return fallback;
        },
        Login: function(redirectUri) {
            if (!redirectUri) redirectUri = location.href;
            var data = {
                scope: GithubComments.SCOPE,
                redirect_uri: redirectUri,
                client_id: GithubComments._clientId,
                client_secret: GithubComments._clientSecret
            };
            location.href = 'https://github.com/login/oauth/authorize?' + Object.keys(data).map(function(k) {
                return encodeURIComponent(k) + '=' + encodeURIComponent(data[k])
            }).join('&');
        },
        Logout: function() {
            localStorage.removeItem(GithubComments.ACCESS_TOKEN_NAME);
            GithubComments._accessToken = undefined;
            GithubComments.User._userInfo = undefined;
        },
        GetAccessToken: async function(code) {
            if (GithubComments._accessToken) {
                return GithubComments._accessToken;
            }

            if (!code) {
                var url = window.location.href;
                var start = url.indexOf('?');
                var paramsStr = url.slice(start + 1);
                var paramsStr = paramsStr.split('&');
                var params = {};
                for (index in paramsStr) {
                    var keyValue = paramsStr[index].split('=');
                    params[keyValue[0]] = keyValue[1];
                }

                if (params[GithubComments.PARAM_CODE])
                    code = params[GithubComments.PARAM_CODE];
            }

            if (!code) {
                return undefined;
            }

            try {
                var response = await GithubComments.Request({
                    method: 'POST',
                    url: GithubComments.CORS_ANYWHERE + 'https://github.com/login/oauth/access_token',
                    data: {
                        'client_id': GithubComments._clientId,
                        'client_secret': GithubComments._clientSecret,
                        'code': code
                    },
                    headers: {
                        Accept: GithubComments.ACCEPT_JSON,
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    timeout: GithubComments.User.REQUEST_TIMEOUT,
                });
            } catch (error) {
                throw new Error(GithubComments.User.GetErrorMessage(
                    error,
                    'GitHub 登录授权失败，请稍后重试。'
                ));
            }

            if (!response.data.access_token) {
                throw new Error(
                    response.data.error_description || response.data.error || 'GitHub 登录授权失败，请重试。'
                );
            }

            GithubComments._accessToken = response.data.access_token;
            localStorage.setItem(GithubComments.ACCESS_TOKEN_NAME, response.data.access_token);
            return response.data.access_token;
        },
        Get: async function() {
            var accessToken = await GithubComments.User.GetAccessToken();
            if (!accessToken) return undefined;

            if (GithubComments.User._userInfo) {
                return GithubComments.User._userInfo;
            }

            try {
                var response = await GithubComments.Request({
                    url: "https://api.github.com/user",
                    dataType: 'json',
                    headers: {
                        'Authorization': 'token ' + accessToken
                    },
                    timeout: GithubComments.User.REQUEST_TIMEOUT
                });
            } catch (error) {
                GithubComments.User.Logout();
                throw new Error(GithubComments.User.GetErrorMessage(
                    error,
                    '无法读取 GitHub 登录信息，请重试。'
                ));
            }

            GithubComments.User._userInfo = response.data;
            return response.data;
        },
        IsLogin: function() {
            return Boolean(GithubComments.User._userInfo);
        }
    },
    Comments: {
        Get: async function(issueId, page) {
            if (!issueId) {
                throw new Error(GithubComments.ERROR.ISSUE_ID_NOT_EXIST);
            }
            if (!page) {
                page = 1;
            }
            var cacheKey = GithubComments.COMMENTS_CACHE_PREFIX + issueId + '_' + page;
            var cached = GithubComments.Cache.Get(cacheKey);
            if (cached) return cached;

            try {
                var response = await GithubComments.Request({
                    url: GithubComments.GITHUB_GPI + '/repos/' + GithubComments._owner + '/' + GithubComments._repos + '/issues/' + issueId + '/comments?per_page=' + GithubComments.PER_PAGE + '&page=' + page,
                    dataType: 'json',
                    headers: {
                        Accept: 'application/vnd.github.VERSION.html+json',
                        'X-Requested-With': 'XMLHttpRequest'
                    }
                });
            } catch (error) {
                if (error.request && error.request.status === 404) {
                    throw new Error(GithubComments.ERROR.ISSUE_NOT_FOUND);
                }
                if (error.request && error.request.status === 403 && error.request.responseJSON) {
                    throw new Error(error.request.responseJSON.message);
                }
                throw new Error(GithubComments.ERROR.UNHANDLE_EXCEPTION);
            }

            var links = response.request.getResponseHeader('Link');
            var link_array = [];
            if (links) {
                links = links.split(',');
                for (var i = 0; i < links.length; i++) {
                    link_array.push({
                        'page': links[i].match(/&page=(\d+)/i)[1],
                        'ref': links[i].match(/rel=\"(.+)\"/i)[1]
                    });
                }
            }

            var result = {
                'data': response.data,
                'links': link_array
            };
            GithubComments.Cache.Set(cacheKey, result);
            return result;
        },
        Add: async function(issueId, commentText) {
            if (!GithubComments.User.IsLogin()) {
                throw new Error(GithubComments.ERROR.NOT_LOGIN);
            }

            try {
                var response = await GithubComments.Request({
                    method: 'POST',
                    url: GithubComments.GITHUB_GPI + '/repos/' + GithubComments._owner + '/' + GithubComments._repos + '/issues/' + issueId + '/comments',
                    headers: {
                        'Authorization': 'token ' + GithubComments._accessToken,
                        Accept: 'application/vnd.github.VERSION.html+json',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    data: JSON.stringify({
                        'body': commentText
                    }),
                    dataType: 'json'
                }
                );
            } catch (error) {
                throw new Error(GithubComments.User.GetErrorMessage(
                    error,
                    '评论提交失败，请稍后重试。'
                ));
            }

            GithubComments.Cache.ClearIssue(issueId);
            return response.data;
        },
        Count: async function(issueId) {
            if (!issueId) {
                throw new Error(GithubComments.ERROR.ISSUE_ID_NOT_EXIST);
            }
            var cacheKey = GithubComments.COMMENTS_COUNT_CACHE_PREFIX + issueId;
            var cached = GithubComments.Cache.Get(cacheKey);
            if (cached) return cached;

            try {
                var response = await GithubComments.Request({
                    url: "https://api.github.com/repos/" + GithubComments._owner + "/" + GithubComments._repos + "/issues/" + issueId,
                    dataType: 'json'
                });
            } catch (error) {
                if (error.request && error.request.status === 404) {
                    throw new Error(GithubComments.ERROR.ISSUE_NOT_FOUND);
                }
                throw new Error(GithubComments.ERROR.UNHANDLE_EXCEPTION);
            }

            if (response.data.comments < 0) {
                throw new Error(GithubComments.ERROR.UNHANDLE_EXCEPTION);
            }

            var result = {
                'number': response.data.number,
                'count': response.data.comments
            };
            GithubComments.Cache.Set(cacheKey, result);
            return result;
        }
    },
    Emoji: {
        GetAliases: function() {
            if (!GithubComments._emojiJson) return [];
            return Object.keys(GithubComments._emojiJson).sort();
        },
        Init: async function() {
            var response = await GithubComments.Request({
                method: 'GET',
                url: GithubComments.GITHUB_GPI + '/emojis',
                headers: {
                    Accept: GithubComments.ACCEPT_JSON,
                }
            });
            localStorage.setItem(GithubComments.EMOJI_JSON, JSON.stringify(response.data));
            GithubComments._emojiJson = response.data;
            return response.data;
        },
        Parse: function(text) {
            var result = text;
            var emojiList = text.match(/:.+?:/g);
            if (!emojiList) return result;
            for (index in emojiList) {
                var emoji = emojiList[index];
                var emojiShort = emojiList[index].slice(1, -1);
                if (GithubComments._emojiJson && GithubComments._emojiJson[emojiShort]) {
                    result = result.replace(emoji, '<img class="emoji" title="' + emojiShort + '" alt="' + emojiShort + '" src="' + GithubComments._emojiJson[emojiShort] + '" height="20" width="20">');
                }
            }
            return result;
        }
    }
}
